import{_ as e,c as t,o as r,ai as n}from"./chunks/framework.BrjRfu4a.js";const k=JSON.parse('{"title":"국내외 경제상황 | 2024년 국고채 시장 | 한국 국채","description":"2024년 글로벌 경제는 지정학적 불확실성 확대, 미국 달러화 강세, 인플레이션 하락세 둔화와 함께 미국 등의 높은 금리 수준이 상반기까지 지속되며 경기 회복이 제한되는 모습을 보였습니다. 이러한 경제 환경 속에서 한국의 국고채 시장은 상대적으로 안정적인 움직임을 보이며 국가 재정정책을 뒷받침하는 역할을 수행했습니다.","frontmatter":{"title":"국내외 경제상황 | 2024년 국고채 시장 | 한국 국채","description":"2024년 글로벌 경제는 지정학적 불확실성 확대, 미국 달러화 강세, 인플레이션 하락세 둔화와 함께 미국 등의 높은 금리 수준이 상반기까지 지속되며 경기 회복이 제한되는 모습을 보였습니다. 이러한 경제 환경 속에서 한국의 국고채 시장은 상대적으로 안정적인 움직임을 보이며 국가 재정정책을 뒷받침하는 역할을 수행했습니다.","head":[["meta",{"property":"og:title","content":"국내외 경제상황 | 2024년 국고채 시장 | 한국 국채"}],["meta",{"property":"og:description","content":"2024년 글로벌 경제는 지정학적 불확실성 확대, 미국 달러화 강세, 인플레이션 하락세 둔화와 함께 미국 등의 높은 금리 수준이 상반기까지 지속되며 경기 회복이 제한되는 모습을 보였습니다. 이러한 경제 환경 속에서 한국의 국고채 시장은 상대적으로 안정적인 움직임을 보이며 국가 재정정책을 뒷받침하는 역할을 수행했습니다."}],["meta",{"property":"og:image","content":"/images/RiskQuantHaun.png"}],["meta",{"property":"og:url","content":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/2024-market/"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/2024-market/"}],["link",{"rel":"alternate","hreflang":"en","href":"https://risk-quant-haun.github.io/korean-treasury-bonds/2024-market/"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/2024-market/"}],["link",{"rel":"canonical","href":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/2024-market/"}]],"date":"2025-03-06T00:00:00.000Z"},"headers":[],"relativePath":"ko/korean-treasury-bonds/2024-market/index.md","filePath":"ko/korean-treasury-bonds/2024-market/index.md"}'),o={name:"ko/korean-treasury-bonds/2024-market/index.md"};function i(s,a,l,h,d,p){return r(),t("div",null,a[0]||(a[0]=[n('<h1 id="🏦-국내외-경제상황" tabindex="-1">🏦 국내외 경제상황 <a class="header-anchor" href="#🏦-국내외-경제상황" aria-label="Permalink to &quot;🏦 국내외 경제상황&quot;">​</a></h1><p><strong>2024년 국고채 시장 | 한국 국채 | 2025.03.06</strong></p><h2 id="_1️⃣-글로벌-경제-환경" tabindex="-1">1️⃣ 글로벌 경제 환경 <a class="header-anchor" href="#_1️⃣-글로벌-경제-환경" aria-label="Permalink to &quot;1️⃣ 글로벌 경제 환경&quot;">​</a></h2><p>2024년 글로벌 경제는 지정학적 불확실성 확대, 미국 달러화 강세, 인플레이션 하락세 둔화와 함께 미국 등의 높은 금리 수준이 상반기까지 지속되며 경기 회복이 제한되는 모습을 보였습니다.</p><p>당초에는 인플레이션 둔화 흐름 속에 각국의 통화정책 기조가 완화적으로 전환하면서 경기가 회복할 것으로 예상되었으나, 중동지역의 지정학적 리스크 확대로 국제 유가가 반등했습니다(WTI 기준, 86.9$/배럴까지 상승). 또한 트럼프 2기 행정부의 재정·관세·이민 정책 등에 따른 인플레이션 재점화 우려로 주요국 중앙은행의 금리 인하가 제한되면서 경기 회복세가 둔화되었습니다.</p><h2 id="_2️⃣-글로벌-금융시장-동향" tabindex="-1">2️⃣ 글로벌 금융시장 동향 <a class="header-anchor" href="#_2️⃣-글로벌-금융시장-동향" aria-label="Permalink to &quot;2️⃣ 글로벌 금융시장 동향&quot;">​</a></h2><p>글로벌 금융시장은 미국 경기지표의 호조가 지속되고 인플레이션 하락세가 둔화되는 모습을 보여주면서 달러 강세 흐름이 지속되었고, 연준의 금리 인하 예상 폭이 축소 전망됨에 따라 글로벌 유동성이 유입되며 신흥국 대비 미국 주식시장의 강세가 이어졌습니다.</p><h2 id="_3️⃣-한국-경제와-금융시장-상황" tabindex="-1">3️⃣ 한국 경제와 금융시장 상황 <a class="header-anchor" href="#_3️⃣-한국-경제와-금융시장-상황" aria-label="Permalink to &quot;3️⃣ 한국 경제와 금융시장 상황&quot;">​</a></h2><p>한국의 금융·외환시장은 변동성이 큰 모습을 보였습니다. 주가는 상반기까지 양호한 흐름을 보였으나, 하반기부터 미국 신정부의 정책 변화 등 대내외 불확실성과 반도체 등 업종별 실적 우려 등으로 부진한 모습을 보였고, 달러-원 환율은 2008년 글로벌 금융위기 이후 최고 수준까지 상승하였습니다(달러-원 환율 기준 1,472.5원).</p><p>한편, 국내경제는 글로벌 복합위기에서 회복되는 모습을 보였으나, 하반기 이후 대내외 불확실성이 커지면서 경기 하방위험이 확대되었습니다. 경기는 반도체 업황 개선 등에 힘입어 수출 중심의 성장세를 보였으나, 더딘 내수 회복속도와 미국 신정부 출범 등에 따른 대내외 불확실성 등으로 연간 2.0% 성장했습니다.</p><h2 id="_4️⃣-물가-동향" tabindex="-1">4️⃣ 물가 동향 <a class="header-anchor" href="#_4️⃣-물가-동향" aria-label="Permalink to &quot;4️⃣ 물가 동향&quot;">​</a></h2><p>물가는 전방위적 민생안정 대책 추진 등에 힘입어 물가안정목표 수준인 2%대(2.3%)를 기록하며 위기 이전 수준을 회복했습니다. 이는 한국 경제의 안정화 노력이 일정 부분 성과를 거두었음을 보여줍니다.</p><h2 id="_5️⃣-시장-지표-추이" tabindex="-1">5️⃣ 시장 지표 추이 <a class="header-anchor" href="#_5️⃣-시장-지표-추이" aria-label="Permalink to &quot;5️⃣ 시장 지표 추이&quot;">​</a></h2><p>2024년의 주요 시장 지표들은 다음과 같은 추이를 보였습니다:</p><ol><li><strong>국제유가</strong>: 중동 지정학적 리스크로 인해 상승세를 보이며 WTI 기준 86.9$/배럴까지 상승</li><li><strong>달러인덱스 및 달러-원 환율</strong>: 달러 강세 지속으로 원화 가치 하락, 달러-원 환율 1,472.5원까지 상승</li><li><strong>주가</strong>: 상반기 양호한 흐름 이후 하반기 부진</li><li><strong>금리</strong>: 글로벌 통화정책 변화와 함께 변동성 확대</li></ol><p>이러한 경제 환경 속에서 한국의 국고채 시장은 상대적으로 안정적인 움직임을 보이며 국가 재정정책을 뒷받침하는 역할을 수행했습니다.</p>',16)]))}const c=e(o,[["render",i]]);export{k as __pageData,c as default};
